---FreshUI
---@param data table
---@param progress number
---@param subCategory table
function CatHouseFilterPopupFlowNode:FreshUI(data, progress, subCategory, isClearSelect)
    self.data = data
    if data.id == ChildFilterId then
        ---可能存子项选择的情况
        self.TextType.text = string.format('%s:\n (%d/%d)', tostring(self.data.name), progress, ChildrenMaxCount)
    else
        self.TextType.text = string.format('%s:', tostring(data.name))
    end
    local parentGo = self.controller.gameObject
    for i, v in pairs(data.condition) do
        if isClearSelect then
            v.selected = false
        end
        local go = self.LabelNodes[v.id]
        if go == nil then
            go = KTool.Instantiate(parentGo, self.LabelNode.gameObject, false) 
            go.name = "LabelNode" .. tostring(v.id)
            KTool.SetActive(go, true)
            self.LabelNodes[v.id] = go
        end 
        ---@type CatHouseFilterPopupFlowCellNode
        local env = CfUtils.GetLuaScr(go, CatHouseFilterPopupFlowCellNodePath)
        if not isNull(env) then
            local progress = 0
            if checkNumber(data.id) == ChildFilterId then
                ---存在子项
                if subCategory[tostring(v.id)] then
                    progress = table.count(subCategory[tostring(v.id)])
                end
            end
            env:FreshUI(data.id, v, progress)
        end
    end
end


